2	import { WebSocketState } from "./types";
3	
4	/**
5	 * Check if the app is in a closed/disconnected state
6	 */
7	export function isAppClosed(state: WebSocketState): boolean {
8	  return state === WebSocketState.CLOSED;
9	}
10	
11	/**
12	 * Check if the app is in a connecting state
13	 */
14	export function isAppConnecting(state: WebSocketState): boolean {
15	  return state === WebSocketState.CONNECTING;
16	}
17	
18	/**
19	 * Check if the app is in an open/connected state
20	 */
21	export function isAppConnected(state: WebSocketState): boolean {
22	  return state === WebSocketState.OPEN;
23	}
24	
25	/**
26	 * Check if the app is in a closing state
27	 */
28	export function isAppClosing(state: WebSocketState): boolean {
29	  return state === WebSocketState.CLOSING;
30	}
31	
32	/**
33	 * Check if the app is in a not started state
34	 */
35	export function isAppNotStarted(state: WebSocketState): boolean {
36	  return state === WebSocketState.NOT_STARTED;
37	}
38	
39	/**
40	 * Check if the app is in a state where user interactions should be disabled
41	 */
42	export function isAppInteractionDisabled(state: WebSocketState): boolean {
43	  return (
44	    state === WebSocketState.CLOSED ||
45	    state === WebSocketState.CLOSING ||
46	    state === WebSocketState.CONNECTING
47	  );
48	}
49	
50	/**
51	 * Get a human-readable tooltip message for the connection state
52	 */
53	export function getConnectionTooltip(state: WebSocketState): string {
54	  switch (state) {
55	    case WebSocketState.CLOSED:
56	      return "App disconnected";
57	    case WebSocketState.CONNECTING:
58	      return "Connecting to a runtime ...";
59	    case WebSocketState.CLOSING:
60	      return "App disconnecting...";
61	    case WebSocketState.OPEN:
62	      return "";
63	    case WebSocketState.NOT_STARTED:
64	      return "Click to connect to a runtime";
65	    default:
66	      return "";
67	  }
