3	import { atom, useAtomValue, useSetAtom } from "jotai";
4	import { AlertCircleIcon, CheckCircle2Icon, PowerOffIcon } from "lucide-react";
5	import type React from "react";
6	import { Spinner } from "@/components/icons/spinner";
7	import { Tooltip } from "@/components/ui/tooltip";
8	import { connectionAtom } from "@/core/network/connection";
9	import { useConnectToRuntime, useRuntimeManager } from "@/core/runtime/config";
10	import { store } from "@/core/state/jotai";
11	import { isWasm } from "@/core/wasm/utils";
12	import {
13	  isAppClosing,
14	  isAppConnected,
15	  isAppConnecting,
16	  isAppNotStarted,
17	} from "@/core/websocket/connection-utils";
18	import { useAsyncData } from "@/hooks/useAsyncData";
19	import { useInterval } from "@/hooks/useInterval";
20	import { Strings } from "@/utils/strings";
21	
22	const CHECK_HEALTH_INTERVAL_MS = 30_000;
23	
24	type ConnectionStatus = "healthy" | "unhealthy" | "connecting" | "disconnected";
25	
26	// Atom to track connection status for use in other components
27	export const connectionStatusAtom = atom<ConnectionStatus>("connecting");
28	
29	export function getConnectionStatus(): ConnectionStatus {
30	  return store.get(connectionStatusAtom);
31	}
32	
33	/**
34	 * Backend connection status indicator for the developer panel header
35	 */
36	export const BackendConnectionStatus: React.FC = () => {
37	  const connection = useAtomValue(connectionAtom).state;
38	  const runtime = useRuntimeManager();
39	  const connectToRuntime = useConnectToRuntime();
40	  const setConnectionStatus = useSetAtom(connectionStatusAtom);
41	
42	  const { isFetching, error, data, refetch } = useAsyncData(async () => {
43	    // If the connection is not connected, return
44	    if (!isAppConnected(connection)) {
45	      setConnectionStatus("disconnected");
46	      return;
47	    }
48	
49	    // Skip wasm since there is no health check for wasm
50	    if (isWasm()) {
51	      setConnectionStatus("healthy");
52	      return {
53	        isHealthy: true,
54	        lastChecked: new Date(),
55	        error: undefined,
56	      };
57	    }
58	
59	    try {
60	      const isHealthy = await runtime.isHealthy();
61	      setConnectionStatus(isHealthy ? "healthy" : "unhealthy");
62	      return {
63	        isHealthy,
64	        lastChecked: new Date(),
65	        error: undefined,
66	      };
67	    } catch (error) {
68	      setConnectionStatus("unhealthy");
69	      return {
70	        isHealthy: false,
71	        lastChecked: new Date(),
72	        error: error instanceof Error ? error.message : "Unknown error",
73	      };
74	    }
75	  }, [runtime, connection]);
76	
77	  useInterval(refetch, {
78	    delayMs: isAppConnected(connection) ? CHECK_HEALTH_INTERVAL_MS : null,
79	    whenVisible: true,
80	  });
81	
82	  const getStatusInfo = () => {
83	    if (isAppNotStarted(connection)) {
84	      return "Not connected to a runtime";
85	    }
86	
87	    const baseStatus = Strings.startCase(connection.toLowerCase());
88	    const healthInfo = data?.lastChecked
89	      ? data.isHealthy
90	        ? "✓ Healthy"
91	        : "✗ Unhealthy"
92	      : "Health: Unknown";
93	
94	    const errorInfo = error ? `Error: ${error}` : "";
95	
96	    return [baseStatus, healthInfo, errorInfo].filter(Boolean).join("\n");
97	  };
98	
99	  const getStatusIcon = () => {
100	    if (isFetching || isAppConnecting(connection)) {
101	      return <Spinner size="small" />;
102	    }
103	
104	    if (isAppClosing(connection)) {
105	      return <Spinner className="text-destructive" size="small" />;
106	    }
107	
108	    if (isAppConnected(connection)) {
109	      if (data?.isHealthy) {
110	        return <CheckCircle2Icon className="w-4 h-4 text-(--green-9)" />;
111	      }
112	      if (data?.lastChecked) {
113	        return <AlertCircleIcon className="w-4 h-4 text-(--yellow-9)" />;
114	      }
115	      return <CheckCircle2Icon className="w-4 h-4" />;
116	    }
117	    if (isAppNotStarted(connection)) {
118	      return <PowerOffIcon className="w-4 h-4" />;
119	    }
120	
121	    return <PowerOffIcon className="w-4 h-4 text-red-500" />;
122	  };
123	
124	  const handleClick = () => {
125	    if (isAppNotStarted(connection)) {
126	      void connectToRuntime();
127	    } else {
128	      refetch();
129	    }
130	  };
131	
132	  return (
133	    <Tooltip
134	      content={
135	        <div className="text-sm whitespace-pre-line">
136	          {getStatusInfo()}
137	          {isAppConnected(connection) && (
138	            <div className="mt-2 text-xs text-muted-foreground">
139	              Click to refresh health status
140	            </div>
141	          )}
142	        </div>
143	      }
144	      data-testid="footer-backend-status"
145	    >
146	      <button
147	        type="button"
148	        onClick={handleClick}
149	        className="p-1 hover:bg-accent rounded flex items-center gap-1.5 text-xs text-muted-foreground"
150	        data-testid="backend-status"
151	      >
152	        {getStatusIcon()}
153	        <span>Kernel</span>
154	      </button>
155	    </Tooltip>
156	  );
157	};
