import ReconnectingWebSocket from "partysocket/ws";
import {
  type ConnectionEvent,
  type ConnectionTransportCallback,
  type IConnectionTransport,
} from "./transport";

// Per-`reconnect()` retry budget for partysocket. After exhaustion, partysocket
// stops silently; `WsTransport` detects `retryCount >= MAX_RETRIES` and rewrites
// the close reason to `TRANSPORT_EXHAUSTED_REASON` so callers can surface the
// give-up instead of spinning forever.
export const MAX_RETRIES = 10;

// Synthetic close reason injected by `WsTransport` once the retry budget is
// exhausted. `classifyCloseEvent` recognizes this as the terminal "gave-up"
// signal.
export const TRANSPORT_EXHAUSTED_REASON = "MARIMO_TRANSPORT_EXHAUSTED";

type AnyCallback = ConnectionTransportCallback<ConnectionEvent>;
type WrapperCallback = (event: unknown) => void;

/**
 * A connection transport backed by partysocket's {@link ReconnectingWebSocket}.
 *
 * It transparently forwards events to registered listeners, but intercepts
 * "close" events: once the underlying socket's `retryCount` reaches
 * {@link MAX_RETRIES}, the close reason is rewritten to
 * {@link TRANSPORT_EXHAUSTED_REASON} before being handed to listeners. This
 * gives callers a durable signal that the transport has given up, since
 * partysocket otherwise stops retrying silently.
 */
export class WsTransport implements IConnectionTransport {
  private readonly inner: ReconnectingWebSocket;

  // For each event, maps an original callback to the wrapper actually
  // registered on the underlying socket. Used to deduplicate registrations and
  // to remove the exact wrapper on `removeEventListener`.
  private readonly wrappers = new Map<
    ConnectionEvent,
    Map<AnyCallback, WrapperCallback>
  >();

  constructor(urlFactory: () => string) {
    this.inner = new ReconnectingWebSocket(urlFactory, undefined, {
      maxRetries: MAX_RETRIES,
      debug: false,
      startClosed: true,
      // long timeout -- the server can become slow when many notebooks
      // are open.
      connectionTimeout: 10_000,
    });
  }

  get readyState(): WebSocket["readyState"] {
    return this.inner.readyState as WebSocket["readyState"];
  }

  get retryCount(): number {
    return this.inner.retryCount;
  }

  reconnect(code?: number | undefined, reason?: string | undefined): void {
    this.inner.reconnect(code, reason);
  }

  close(): void {
    this.inner.close();
  }

  send(data: string | ArrayBuffer | Blob | ArrayBufferView): void {
    this.inner.send(data);
  }

  addEventListener<T extends ConnectionEvent>(
    event: T,
    callback: ConnectionTransportCallback<T>,
  ): void {
    let forEvent = this.wrappers.get(event);
    if (!forEvent) {
      forEvent = new Map();
      this.wrappers.set(event, forEvent);
    }

    const original = callback as AnyCallback;
    // Deduplicate: registering the same callback twice must only fire once.
    if (forEvent.has(original)) {
      return;
    }

    const wrapper: WrapperCallback =
      event === "close"
        ? (rawEvent) => original(this.rewriteCloseEvent(rawEvent))
        : (rawEvent) => original(rawEvent as never);

    forEvent.set(original, wrapper);
    this.inner.addEventListener(
      event,
      wrapper as (event: WebSocketEventMap[T]) => void,
    );
  }

  removeEventListener<T extends ConnectionEvent>(
    event: T,
    callback: ConnectionTransportCallback<T>,
  ): void {
    const forEvent = this.wrappers.get(event);
    if (!forEvent) {
      return;
    }
    const original = callback as AnyCallback;
    const wrapper = forEvent.get(original);
    if (!wrapper) {
      return;
    }
    forEvent.delete(original);
    this.inner.removeEventListener(
      event,
      wrapper as (event: WebSocketEventMap[T]) => void,
    );
  }

  /**
   * When the retry budget is exhausted, rewrite the close reason so callers can
   * detect the give-up. The rewrite takes precedence over any server-sent
   * reason. Otherwise, forward the original event unchanged.
   */
  private rewriteCloseEvent(rawEvent: unknown): CloseEvent {
    const event = rawEvent as CloseEvent;
    if (this.inner.retryCount < MAX_RETRIES) {
      return event;
    }

    try {
      return new CloseEvent("close", {
        code: event?.code,
        reason: TRANSPORT_EXHAUSTED_REASON,
        wasClean: event?.wasClean ?? false,
      });
    } catch {
      // Environments without a CloseEvent constructor: fall back to a plain
      // object that preserves the fields callers read.
      return {
        ...event,
        reason: TRANSPORT_EXHAUSTED_REASON,
      } as CloseEvent;
    }
  }
}
