// @vitest-environment jsdom
import { describe, expect, it, vi } from "vitest";
import { MAX_RETRIES, TRANSPORT_EXHAUSTED_REASON, WsTransport } from "./ws";

function fakeInner(retryCount: number) {
  const listeners = new Map<string, Set<(e: unknown) => void>>();
  return {
    retryCount,
    readyState: 3,
    addEventListener: vi.fn((ev: string, cb: (e: unknown) => void) => {
      if (!listeners.has(ev)) {
        listeners.set(ev, new Set());
      }
      listeners.get(ev)?.add(cb);
    }),
    removeEventListener: vi.fn((ev: string, cb: (e: unknown) => void) => {
      listeners.get(ev)?.delete(cb);
    }),
    fire(ev: string, data: unknown) {
      for (const cb of listeners.get(ev) ?? []) {
        cb(data);
      }
    },
    count(ev: string) {
      return listeners.get(ev)?.size ?? 0;
    },
  };
}

describe("WsTransport", () => {
  it("exports constants", () => {
    expect(TRANSPORT_EXHAUSTED_REASON).toBe("MARIMO_TRANSPORT_EXHAUSTED");
    expect(typeof MAX_RETRIES).toBe("number");
  });

  it("rewrites reason on exhaustion even with server reason", () => {
    const t = new WsTransport(() => "ws://x");
    const inner = fakeInner(MAX_RETRIES);
    (t as unknown as { inner: unknown }).inner = inner;
    const cb = vi.fn();
    t.addEventListener("close", cb);
    inner.fire("close", { code: 1006, reason: "MARIMO_ALREADY_CONNECTED" });
    expect(cb).toHaveBeenCalledTimes(1);
    expect(cb.mock.calls[0][0].reason).toBe(TRANSPORT_EXHAUSTED_REASON);
  });

  it("forwards original reason below budget", () => {
    const t = new WsTransport(() => "ws://x");
    const inner = fakeInner(MAX_RETRIES - 1);
    (t as unknown as { inner: unknown }).inner = inner;
    const cb = vi.fn();
    t.addEventListener("close", cb);
    inner.fire("close", { code: 1006, reason: "server-reason" });
    expect(cb.mock.calls[0][0].reason).toBe("server-reason");
  });

  it("dedups add and fully removes with one call", () => {
    const t = new WsTransport(() => "ws://x");
    const inner = fakeInner(0);
    (t as unknown as { inner: unknown }).inner = inner;
    const cb = vi.fn();
    t.addEventListener("close", cb);
    t.addEventListener("close", cb);
    t.addEventListener("close", cb);
    expect(inner.count("close")).toBe(1);
    inner.fire("close", { reason: "" });
    expect(cb).toHaveBeenCalledTimes(1);
    t.removeEventListener("close", cb);
    expect(inner.count("close")).toBe(0);
    cb.mockClear();
    inner.fire("close", { reason: "" });
    expect(cb).not.toHaveBeenCalled();
  });
});
